const form = $('SubmitSource').first().json;

// Source text came either from the fetched page or straight from the textarea.
let sourceText = '';
let sourceTitle = '';

try {
  sourceText = $json.articleText || '';
  sourceTitle = $json.pageTitle || form['Source URL'] || 'Untitled source';
} catch (e) { sourceText = ''; }

if (!sourceText || sourceText.length < 200) {
  sourceText = form['Or paste the text'] || '';
  sourceTitle = sourceTitle || 'Pasted text';
}

if (!sourceText || sourceText.length < 200) {
  throw new Error('No usable source text. Provide a URL that returns an article, or paste at least a few paragraphs.');
}

// Trim to keep the prompt sane and the bill small.
sourceText = sourceText.replace(/\s+/g, ' ').trim().slice(0, 18000);

return [{
  json: {
    sourceText,
    sourceTitle: String(sourceTitle).slice(0, 120),
    postCount: parseInt(form['Posts to generate'], 10) || 12,
    startDate: form['Start date']
  }
}];

const src = $('NormalizeSource').first().json;

const raw = $json.content?.[0]?.text ?? '';
const clean = raw.replace(/```json/g, '').replace(/```/g, '').trim();

let ideas;
try {
  ideas = JSON.parse(clean);
  if (!Array.isArray(ideas)) ideas = [ideas];
} catch (e) {
  throw new Error('Idea extraction returned unparseable output: ' + raw.slice(0, 300));
}

return ideas.map((idea, i) => ({
  json: {
    ...idea,
    sourceTitle: src.sourceTitle,
    startDate: src.startDate,
    ideaIndex: i
  }
}));

const idea = { ...$('BatchIdeas').item.json };

const raw = $json.content?.[0]?.text ?? '';
const clean = raw.replace(/```json/g, '').replace(/```/g, '').trim();

let v;
try {
  v = JSON.parse(clean);
} catch (e) {
  v = { linkedin: '[REVIEW NEEDED] ' + raw.slice(0, 500), instagram: '', facebook: '' };
}

// ---- POSTING WINDOWS — edit these ----
// Sensible B2B starting defaults. Replace with your own numbers once
// you have three months of your own analytics. These are a starting
// point, not a law.
const PLATFORM_TIMES = {
  linkedin:  '09:00',   // weekday mornings, before the working day fills up
  facebook:  '13:00',   // lunchtime scroll
  instagram: '18:30'    // evening, after work
};
// ---------------------------------------

// Spread posts across weekdays from the chosen start date.
// Post i lands on Mon / Wed / Fri of week floor(i/3).
const DAY_OFFSETS = [0, 2, 4];
const i = idea.ideaIndex;
const week = Math.floor(i / 3);
const dayOffset = (week * 7) + DAY_OFFSETS[i % 3];

const start = new Date(idea.startDate);
const scheduled = new Date(start.getTime() + dayOffset * 24 * 60 * 60 * 1000);
const scheduledFor = scheduled.toISOString().slice(0, 10);

const rows = [];
for (const platform of ['linkedin', 'facebook', 'instagram']) {
  const content = v[platform];
  if (!content || !content.trim()) continue;
  rows.push({
    json: {
      sourceTitle: idea.sourceTitle,
      angle: idea.angle,
      platform,
      content,
      scheduledFor,
      scheduledTime: PLATFORM_TIMES[platform],
      status: 'queued'
    }
  });
}

return rows;

const rows = $input.all().map(i => i.json);
if (!rows.length) return [{ json: { html: '<p>Nothing was queued.</p>', total: 0 } }];

const byDate = {};
for (const r of rows) {
  if (!byDate[r.scheduledFor]) byDate[r.scheduledFor] = [];
  byDate[r.scheduledFor].push(r);
}

const dates = Object.keys(byDate).sort();

let html = '<h2>Queued from: ' + rows[0].sourceTitle + '</h2>';
html += '<p><strong>' + rows.length + ' posts</strong> scheduled across ' + dates.length + ' days, from ' + dates[0] + ' to ' + dates[dates.length - 1] + '.</p>';
html += '<p style="color:#666">Everything sits in <code>content_queue</code> with status <code>queued</code>. Edit or delete any row before its date. The daily publisher picks up whatever is due.</p>';

for (const d of dates) {
  html += '<h3 style="margin-top:26px">' + d + '</h3>';
  for (const p of byDate[d]) {
    html += '<div style="border-left:3px solid #ddd;padding:6px 14px;margin:10px 0">';
    html += '<strong style="text-transform:capitalize">' + p.platform + '</strong> — <em>' + p.angle + '</em><br><br>';
    html += String(p.content).slice(0, 400).replace(/\n/g, '<br>');
    if (p.content.length > 400) html += '…';
    html += '</div>';
  }
}

return [{ json: { html, total: rows.length } }];

const results = $input.all().map(i => i.json);
if (!results.length) return [];   // nothing due today — send no email

const ok = results.filter(r => r.status === 'published');
const bad = results.filter(r => r.status === 'failed');

let html = '<h2>Today\'s posts</h2>';
html += '<p>' + ok.length + ' published' + (bad.length ? ', <strong style="color:#b00">' + bad.length + ' failed</strong>' : '') + '.</p>';
if (bad.length) {
  html += '<ul>';
  for (const r of bad) html += '<li>' + r.platform + ' — ' + r.angle + '</li>';
  html += '</ul><p>These are still in the queue marked <code>failed</code>. Retry by setting them back to <code>queued</code>.</p>';
}

return [{ json: { html, published: ok.length, failed: bad.length } }];
